import{c as t,Q as n,j as e,m as s}from"./chunks/framework.BPKcPtvA.js";const b=JSON.parse('{"title":"记忆系统与多模态 RAG","description":"","frontmatter":{},"headers":[],"relativePath":"04-agent-architectures/memory-rag.md","filePath":"04-agent-architectures/memory-rag.md"}'),r={name:"04-agent-architectures/memory-rag.md"};function l(i,a,d,o,p,h){return n(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="记忆系统与多模态-rag" tabindex="-1">记忆系统与多模态 RAG <a class="header-anchor" href="#记忆系统与多模态-rag" aria-label="Permalink to &quot;记忆系统与多模态 RAG&quot;">​</a></h1><blockquote><p>长期记忆与检索增强生成 —— Agent 的知识管理中枢</p></blockquote><h2 id="为什么-agent-需要记忆" tabindex="-1">为什么 Agent 需要记忆？ <a class="header-anchor" href="#为什么-agent-需要记忆" aria-label="Permalink to &quot;为什么 Agent 需要记忆？&quot;">​</a></h2><p>无状态的 LLM 每次调用都是「重新开始」。Agent 要在多轮交互和多个会话中保持连贯性，必须拥有记忆系统。</p><h3 id="人类记忆的工程类比" tabindex="-1">人类记忆的工程类比 <a class="header-anchor" href="#人类记忆的工程类比" aria-label="Permalink to &quot;人类记忆的工程类比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>生物记忆</th><th>Agent 记忆</th><th>生命周期</th><th>技术实现</th></tr></thead><tbody><tr><td>工作记忆</td><td>Context Window</td><td>单次推理</td><td>对话历史</td></tr><tr><td>短期记忆</td><td>会话记忆</td><td>单次会话</td><td>滑动窗口/摘要</td></tr><tr><td>长期记忆</td><td>持久记忆</td><td>跨会话</td><td>向量数据库 + RAG</td></tr></tbody></table><hr><h2 id="rag-架构基础" tabindex="-1">RAG 架构基础 <a class="header-anchor" href="#rag-架构基础" aria-label="Permalink to &quot;RAG 架构基础&quot;">​</a></h2><p>RAG（Retrieval-Augmented Generation）是目前最主流的记忆检索范式。</p><h3 id="标准-rag-流程" tabindex="-1">标准 RAG 流程 <a class="header-anchor" href="#标准-rag-流程" aria-label="Permalink to &quot;标准 RAG 流程&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写入：文档 → 分块(Chunking) → 嵌入(Embedding) → 向量数据库</span></span>
<span class="line"><span>查询：问题 → 嵌入 → 相似度检索 → Top-K 相关块 → 拼入 Prompt → LLM 回答</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="分块策略" tabindex="-1">分块策略 <a class="header-anchor" href="#分块策略" aria-label="Permalink to &quot;分块策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>描述</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>固定大小</strong></td><td>按 Token 数等分</td><td>通用场景</td></tr><tr><td><strong>语义分块</strong></td><td>按语义边界切分</td><td>技术文档</td></tr><tr><td><strong>层次分块</strong></td><td>父子块关系</td><td>长文档问答</td></tr><tr><td><strong>Agentic 分块</strong></td><td>由 Agent 决定切分策略</td><td>复杂知识图谱</td></tr></tbody></table><h3 id="嵌入模型" tabindex="-1">嵌入模型 <a class="header-anchor" href="#嵌入模型" aria-label="Permalink to &quot;嵌入模型&quot;">​</a></h3><p>将文本映射到高维语义向量空间：</p><ul><li><strong>OpenAI</strong>：<code>text-embedding-3-large/small</code></li><li><strong>BGE</strong>：BAAI 开源，MTEB 中文评测领先</li><li><strong>Jina AI</strong>：支持 8K Context，多语言优化</li></ul><h3 id="检索策略演进" tabindex="-1">检索策略演进 <a class="header-anchor" href="#检索策略演进" aria-label="Permalink to &quot;检索策略演进&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>描述</th></tr></thead><tbody><tr><td><strong>Naive Retrieval</strong></td><td>单次检索 + 单次生成</td></tr><tr><td><strong>Multi-hop Retrieval</strong></td><td>多步检索，每次结果指导下一步查询</td></tr><tr><td><strong>Self-RAG</strong></td><td>模型自我判断是否需要检索，评估检索质量</td></tr><tr><td><strong>Corrective RAG</strong></td><td>检索后评估，不相关则重试或转向网络搜索</td></tr><tr><td><strong>GraphRAG</strong></td><td>结合知识图谱的结构化关系增强检索</td></tr></tbody></table><hr><h2 id="多模态-rag" tabindex="-1">多模态 RAG <a class="header-anchor" href="#多模态-rag" aria-label="Permalink to &quot;多模态 RAG&quot;">​</a></h2><p>传统 RAG 仅处理文本，Agent 需要处理多模态知识。</p><h3 id="colpali-colqwen-范式" tabindex="-1">ColPali / ColQwen 范式 <a class="header-anchor" href="#colpali-colqwen-范式" aria-label="Permalink to &quot;ColPali / ColQwen 范式&quot;">​</a></h3><p>新一代多模态检索方案，直接以视觉方式索引文档：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统流程：PDF → OCR → 文本分块 → 文本嵌入 → 检索</span></span>
<span class="line"><span>ColPali： PDF → 页面截图 → 视觉嵌入 → 检索（保留排版、表格、图片信息）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>优势</strong>：</p><ul><li>无需 OCR 管道，避免误差传播</li><li>保留文档的视觉布局信息</li><li>表格、图表、公式等原生支持</li></ul><h3 id="多模态检索架构" tabindex="-1">多模态检索架构 <a class="header-anchor" href="#多模态检索架构" aria-label="Permalink to &quot;多模态检索架构&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户查询（可含图片）</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├─→ 文本检索 → 文本嵌入 → Qdrant/Milvus</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├─→ 图像检索 → 视觉嵌入 → 向量数据库</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └─→ 检索结果融合 → 重排序 → 拼入 LMM Context</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="多模态索引" tabindex="-1">多模态索引 <a class="header-anchor" href="#多模态索引" aria-label="Permalink to &quot;多模态索引&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模态</th><th>索引内容</th><th>嵌入模型</th></tr></thead><tbody><tr><td>文本</td><td>文档段落</td><td>text-embedding-3-large</td></tr><tr><td>图片</td><td>截图/图表</td><td>CLIP/ColPali</td></tr><tr><td>表格</td><td>结构化数据</td><td>文本嵌入 + 元数据过滤</td></tr><tr><td>代码</td><td>代码块</td><td>CodeBERT/UniXCoder</td></tr></tbody></table><hr><h2 id="agent-记忆系统的工程设计" tabindex="-1">Agent 记忆系统的工程设计 <a class="header-anchor" href="#agent-记忆系统的工程设计" aria-label="Permalink to &quot;Agent 记忆系统的工程设计&quot;">​</a></h2><h3 id="三大模块" tabindex="-1">三大模块 <a class="header-anchor" href="#三大模块" aria-label="Permalink to &quot;三大模块&quot;">​</a></h3><ol><li><p><strong>语义记忆（Semantic Memory）</strong></p><ul><li>存储事实、概念、知识</li><li>向量数据库 + RAG</li><li>用户偏好、项目上下文等</li></ul></li><li><p><strong>情景记忆（Episodic Memory）</strong></p><ul><li>存储历史交互序列</li><li>时间戳索引 + 关键事件摘要</li><li>用于反思和学习</li></ul></li><li><p><strong>程序性记忆（Procedural Memory）</strong></p><ul><li>存储如何完成任务的流程</li><li>存储在代码/配置中</li><li>类似 System Prompt 中的规则和 SOP</li></ul></li></ol><h3 id="记忆衰减与管理" tabindex="-1">记忆衰减与管理 <a class="header-anchor" href="#记忆衰减与管理" aria-label="Permalink to &quot;记忆衰减与管理&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────┐    重要性评分     ┌────────────┐</span></span>
<span class="line"><span>│  短期记忆   │ ───────────────→ │  长期记忆   │</span></span>
<span class="line"><span>│  (Redis)   │                  │ (Qdrant)   │</span></span>
<span class="line"><span>└────────────┘                  └────────────┘</span></span>
<span class="line"><span>      ↑                               │</span></span>
<span class="line"><span>      │        周期性整理/遗忘         │</span></span>
<span class="line"><span>      └───────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">核心权衡</p><p>记忆系统的本质是在<strong>检索精度</strong>、<strong>检索速度</strong>和<strong>存储成本</strong>之间的工程权衡。不是所有信息都值得被记住 —— 好的记忆系统需要主动的遗忘机制。</p></div>`,37)])])}const u=t(r,[["render",l]]);export{b as __pageData,u as default};
